const dtL=(i,l)=>{const x=DL[Math.min(DL.length-1,i)];return l==='en'?`${DAYN.en[x.dow]}, ${MONN.en[x.m]} ${x.n}`:l==='es'?`${DAYN.es[x.dow]} ${x.n} de ${MONN.es[x.m]}`:l==='pt'?`${DAYN.pt[x.dow]}, ${x.n} de ${MONN.pt[x.m]}`:`${DAYN.ht[x.dow]} ${x.n} ${MONN.ht[x.m]}`;};
